/**
 * What `theme-preference.tsx` (device) and `theme-preference.web.tsx` (the web, Expo's and the
 * DOM's) share: the preference's type, where it is stored, and the pre-paint script.
 *
 * A separate module for the usual reason: Metro resolves `./theme-preference` to the `.web.tsx`
 * on web, so the web file cannot import shared pieces from it without importing itself.
 */

/** Which palette to paint. `system` follows the device and is what nothing stored means. */
export type ThemePreference = "light" | "dark" | "system";

/** In the order a picker shows them. */
export const THEME_PREFERENCES: readonly ThemePreference[] = ["light", "dark", "system"];

/**
 * The key the preference is stored under, on both platforms. One key rather than an option: the
 * picker's own hook, the one at the app's root and the pre-paint script all have to agree on it,
 * and a key passed to one of them and not the others is a picker that writes where nothing reads.
 */
export const THEME_STORAGE_KEY = "cubeui-theme";

export function isThemePreference(value: unknown): value is ThemePreference {
  return value === "light" || value === "dark" || value === "system";
}

/**
 * Where the device keeps the preference. `@react-native-async-storage/async-storage` fits as it
 * is; `expo-secure-store` or MMKV fit behind two lambdas. The item takes the shape rather than a
 * package, so it adds no storage dependency to an app that already has one. Either method may
 * return a promise.
 */
export type ThemeStorage = {
  getItem: (key: string) => string | null | undefined | Promise<string | null | undefined>;
  setItem: (key: string, value: string) => void | Promise<void>;
};

/**
 * Which set of colours to paint in, beside the light / dark choice. `default` is cubeui's own and
 * what nothing stored means; the rest are `palettes` in `tokens/palette.mjs`.
 */
export type PalettePreference = "default" | "monokai";

/** In the order a picker shows them. */
export const PALETTE_PREFERENCES: readonly PalettePreference[] = ["default", "monokai"];

/** Where the palette is stored, beside `THEME_STORAGE_KEY` and for the same reason. */
export const PALETTE_STORAGE_KEY = "cubeui-palette";

/**
 * Palettes with no light set. Choosing one is dark whatever the theme says — there is no light
 * Monokai to paint — and a picker shows the theme choice as moot while one is chosen.
 */
export const DARK_ONLY_PALETTES: readonly PalettePreference[] = ["monokai"];

export function isPalettePreference(value: unknown): value is PalettePreference {
  return PALETTE_PREFERENCES.includes(value as PalettePreference);
}

export type ThemePreferenceOptions = {
  /**
   * Device only: where the choice persists between launches. Without one, a choice lasts until
   * the app is closed. Pass it where the app starts; a `useThemePreference()` anywhere else — the
   * one inside `ThemePicker` — writes through it too. The web always uses `localStorage`, because
   * it is the one store the pre-paint script can read before any of the bundle has loaded.
   */
  storage?: ThemeStorage | undefined;
};

/** What `useThemePreference` returns: the stored choice and the one way to change it. */
export type ThemePreferenceState = readonly [
  preference: ThemePreference,
  setPreference: (next: ThemePreference) => void,
];

/** What `usePalettePreference` returns, the same shape. */
export type PalettePreferenceState = readonly [
  palette: PalettePreference,
  setPalette: (next: PalettePreference) => void,
];

/**
 * The web's first paint, before React mounts: the same rule `useThemePreference` applies, as a
 * self-contained script for an inline `<script>` in the page's `<head>`. Render it with
 * `dangerouslySetInnerHTML` where the head is React (Expo's `+html.tsx`, a Next layout); paste the
 * copy in the skill's `controls.md` where it is a static `index.html`. A unit test holds that copy
 * to this string.
 *
 * `dark` goes on `<html>` for Dark, and for System while the device is dark; `light` goes on it for
 * Light only. A dark-only palette is `dark` whatever the theme, and never `light`. A palette other
 * than the default is `data-palette` on `<html>`, which both stylesheets key its colours off. `dist/tokens.native.css` (Expo web) reads both over its `prefers-color-scheme` block;
 * `tokens.web.css` (the DOM registry) has no media query and reads `.dark` alone, which is why
 * System still sets `dark` on a dark device rather than leaving it to a query that stylesheet does
 * not have.
 *
 * Written in ES5 and wrapped in `try`, because it runs before anything else on the page and a
 * browser with storage switched off throws on `localStorage` itself.
 */
export const THEME_PRE_PAINT_SCRIPT =
  "(function(){try{" +
  `var s=localStorage,p=s.getItem(${JSON.stringify(THEME_STORAGE_KEY)}),` +
  `q=s.getItem(${JSON.stringify(PALETTE_STORAGE_KEY)}),` +
  `k=${JSON.stringify(DARK_ONLY_PALETTES)}.indexOf(q)>=0,` +
  'd=k||p==="dark"||(p!=="light"&&matchMedia("(prefers-color-scheme: dark)").matches),' +
  'e=document.documentElement,c=e.classList;c.toggle("dark",d);c.toggle("light",!k&&p==="light");' +
  `if(${JSON.stringify(PALETTE_PREFERENCES.filter((p) => p !== "default"))}.indexOf(q)>=0)` +
  'e.setAttribute("data-palette",q)' +
  "}catch(e){}})();";

/**
 * The theme preference on device. `theme-preference.web.tsx` is the web half — Metro picks it for
 * an Expo app's web build — and `theme-preference-base.ts` holds what the two share.
 *
 * Applying the choice is `Appearance.setColorScheme`: the native tokens follow the system
 * appearance through `prefers-color-scheme`, and that call is what moves it for this app.
 * `"unspecified"` hands it back to the system, which then follows the device by itself — so, unlike
 * the web, System needs no listener here.
 *
 * A palette is the other half, and the appearance knows nothing of it: `PaletteProvider` at the
 * app's root puts its colours over the stylesheet's through NativeWind's `VariableContextProvider`.
 * A dark-only palette also sets the appearance to dark, so `useColorScheme()` and a `dark:` class
 * agree with what is painted.
 *
 * Storing it is the app's: `storage` is an adapter over whatever the app already persists with, so
 * the item depends on no storage package. The read is asynchronous, so the stored choice lands a
 * moment after the first render — while the splash screen is still up, in an app that holds it
 * until its own state is loaded.
 */

import { VariableContextProvider } from "nativewind";
import { type ReactNode, useEffect, useMemo, useSyncExternalStore } from "react";
import { Appearance, useColorScheme } from "react-native";
import {
  DARK_ONLY_PALETTES,
  isPalettePreference,
  isThemePreference,
  PALETTE_STORAGE_KEY,
  type PalettePreference,
  type PalettePreferenceState,
  THEME_STORAGE_KEY,
  type ThemePreference,
  type ThemePreferenceOptions,
  type ThemePreferenceState,
  type ThemeStorage,
} from "@/components/ui/theme-preference-base";
import { cssVariables, paletteFor } from "@/lib/cubeui-theme";

/**
 * One preference per app, held here rather than per hook: the picker's hook and the one at the
 * app's root are the same choice. There is no device to read at import, so nothing does.
 */
let current: ThemePreference = "system";
let currentPalette: PalettePreference = "default";
/** The adapter the most recent hook that passed one was given, so a hook without one writes too. */
let storage: ThemeStorage | null = null;
/** Whether each stored value has been read, or overtaken by a choice made before it arrived. */
const settled = { theme: false, palette: false };
/** Whether the stored values have been asked for, so a second hook does not ask again. */
let loading = false;
const listeners = new Set<() => void>();

/**
 * "Follow the device", in the spelling both sides of React Native 0.82 accept at runtime. From 0.82
 * `setColorScheme` takes `"unspecified"` and hands `null` to the native module as is; before it,
 * `null` was the typed spelling but was turned into `"unspecified"` on the way down anyway. The
 * cast is for the 0.81 types, which do not list the string — it keeps one call compiling on both.
 */
const FOLLOW_SYSTEM = "unspecified" as unknown as Parameters<typeof Appearance.setColorScheme>[0];

function subscribe(onChange: () => void) {
  listeners.add(onChange);
  return () => {
    listeners.delete(onChange);
  };
}

function snapshot() {
  return current;
}

function paletteSnapshot() {
  return currentPalette;
}

/** Both choices at once: a dark-only palette decides the appearance, whatever the theme says. */
function apply() {
  const scheme = DARK_ONLY_PALETTES.includes(currentPalette) ? "dark" : current;
  Appearance.setColorScheme(scheme === "system" ? FOLLOW_SYSTEM : scheme);
  for (const listener of listeners) listener();
}

function persist(key: string, value: string) {
  if (!storage) return;
  Promise.resolve(storage.setItem(key, value)).catch(() => {
    // Not persisted, but still applied: the app should not ignore the tap.
  });
}

/** Module-level, so every caller's setter is the same function and safe in a dependency list. */
function setPreference(next: ThemePreference) {
  settled.theme = true;
  current = next;
  apply();
  persist(THEME_STORAGE_KEY, next);
}

function setPalette(next: PalettePreference) {
  settled.palette = true;
  currentPalette = next;
  apply();
  persist(PALETTE_STORAGE_KEY, next);
}

/** Read both stored choices once, the first time a hook is handed somewhere to read them from. */
function load(adapter: ThemeStorage) {
  storage = adapter;
  if (loading) return;
  loading = true;
  Promise.all([adapter.getItem(THEME_STORAGE_KEY), adapter.getItem(PALETTE_STORAGE_KEY)])
    .then(([theme, palette]) => {
      // A choice made while the read was in flight is newer than what it will return.
      let changed = false;
      if (!settled.theme && isThemePreference(theme) && theme !== current) {
        current = theme;
        changed = true;
      }
      if (!settled.palette && isPalettePreference(palette) && palette !== currentPalette) {
        currentPalette = palette;
        changed = true;
      }
      settled.theme = settled.palette = true;
      if (changed) apply();
    })
    .catch(() => {
      // Nothing readable is the same as nothing stored: follow the system, in the default palette.
      settled.theme = settled.palette = true;
    });
}

/**
 * The stored light / dark / system choice, and a setter that stores and applies it. Call it with
 * `storage` where the app starts; the `ThemePicker` and any other caller share that choice. It
 * reads the stored palette too, so the one call at the root covers both.
 */
export function useThemePreference(options: ThemePreferenceOptions = {}): ThemePreferenceState {
  const adapter = options.storage;
  const preference = useSyncExternalStore(subscribe, snapshot, snapshot);

  useEffect(() => {
    if (adapter) load(adapter);
  }, [adapter]);

  return [preference, setPreference] as const;
}

/**
 * The stored palette — `default` or one of `PALETTE_PREFERENCES` — and a setter that stores and
 * applies it, through the same `storage` as the theme. Painting it is `PaletteProvider`'s.
 */
export function usePalettePreference(options: ThemePreferenceOptions = {}): PalettePreferenceState {
  const adapter = options.storage;
  const palette = useSyncExternalStore(subscribe, paletteSnapshot, paletteSnapshot);

  useEffect(() => {
    if (adapter) load(adapter);
  }, [adapter]);

  return [palette, setPalette] as const;
}

/** Stable, so the default palette hands the context the same nothing every render. */
const NO_VARIABLES = {};

/**
 * Wrap the app's root in it — inside nothing that draws — and the chosen palette's colours reach
 * every component under it, a `Modal`'s included, since they travel as React context and not as
 * a stylesheet. The default palette is the stylesheet's own, so it passes no variables; the
 * provider is always there, so a change of palette never remounts the app.
 */
export function PaletteProvider({ children }: { children?: ReactNode }) {
  const palette = useSyncExternalStore(subscribe, paletteSnapshot, paletteSnapshot);
  const scheme = useColorScheme();
  const value = useMemo(
    () =>
      palette === "default"
        ? NO_VARIABLES
        : cssVariables(paletteFor(scheme === "dark" ? "dark" : "light", palette)),
    [palette, scheme],
  );
  return <VariableContextProvider value={value}>{children}</VariableContextProvider>;
}

/**
 * The theme preference on the web — an Expo app's web build, where Metro picks this file over
 * `theme-preference.tsx`, and a DOM app, where it is the whole item. `theme-preference-base.ts`
 * holds what the two halves share.
 *
 * `localStorage` is the store, and the source of truth: the hooks read it through
 * `useSyncExternalStore`, so two components calling a hook, or two tabs, cannot disagree.
 * Applying the choice is a class on `<html>`, and `data-palette` for a palette — see
 * `THEME_PRE_PAINT_SCRIPT` for the rule and why System still sets `dark` on a dark device.
 *
 * Nothing touches `window` at import, and the server snapshots are `system` and `default`, so a
 * server render paints what the pre-paint script is about to correct rather than throwing.
 */

import { Fragment, type ReactNode, useEffect, useSyncExternalStore } from "react";
import {
  DARK_ONLY_PALETTES,
  isPalettePreference,
  isThemePreference,
  PALETTE_STORAGE_KEY,
  type PalettePreference,
  type PalettePreferenceState,
  THEME_STORAGE_KEY,
  type ThemePreference,
  type ThemePreferenceOptions,
  type ThemePreferenceState,
} from "@/components/ui/theme-preference-base";

const DARK_QUERY = "(prefers-color-scheme: dark)";

/** Every hook on the page, told when one of them writes. `storage` events only reach other tabs. */
const listeners = new Set<() => void>();

/** A choice storage refused, so a click still sticks for the life of the page. */
const unsaved: { theme: ThemePreference | null; palette: PalettePreference | null } = {
  theme: null,
  palette: null,
};

function stored(key: string): string | null {
  try {
    return window.localStorage.getItem(key);
  } catch {
    // Storage switched off, or a sandboxed frame: there is nothing to read.
    return null;
  }
}

function read(): ThemePreference {
  if (unsaved.theme) return unsaved.theme;
  const value = stored(THEME_STORAGE_KEY);
  return isThemePreference(value) ? value : "system";
}

function readPalette(): PalettePreference {
  if (unsaved.palette) return unsaved.palette;
  const value = stored(PALETTE_STORAGE_KEY);
  return isPalettePreference(value) ? value : "default";
}

function prefersDark() {
  return typeof window.matchMedia === "function" && window.matchMedia(DARK_QUERY).matches;
}

/** Both choices at once: a dark-only palette decides the class, whatever the theme says. */
function apply(theme = read(), palette = readPalette()) {
  const darkOnly = DARK_ONLY_PALETTES.includes(palette);
  const html = document.documentElement;
  html.classList.toggle(
    "dark",
    darkOnly || theme === "dark" || (theme === "system" && prefersDark()),
  );
  html.classList.toggle("light", !darkOnly && theme === "light");
  if (palette === "default") html.removeAttribute("data-palette");
  else html.setAttribute("data-palette", palette);
}

function subscribe(onChange: () => void) {
  listeners.add(onChange);
  const onStorage = (event: StorageEvent) => {
    if (event.key === THEME_STORAGE_KEY || event.key === PALETTE_STORAGE_KEY || event.key === null)
      onChange();
  };
  window.addEventListener("storage", onStorage);
  return () => {
    listeners.delete(onChange);
    window.removeEventListener("storage", onStorage);
  };
}

function store(key: string, value: string): boolean {
  try {
    window.localStorage.setItem(key, value);
    return true;
  } catch {
    // Not persisted, but still applied: the page should not ignore the click.
    return false;
  }
}

/** Module-level, so every caller's setter is the same function and safe in a dependency list. */
function setPreference(next: ThemePreference) {
  unsaved.theme = store(THEME_STORAGE_KEY, next) ? null : next;
  apply();
  for (const listener of listeners) listener();
}

function setPalette(next: PalettePreference) {
  unsaved.palette = store(PALETTE_STORAGE_KEY, next) ? null : next;
  apply();
  for (const listener of listeners) listener();
}

/**
 * The stored light / dark / system choice, and a setter that stores and applies it. Call it where
 * the app starts, so the choice is applied — and, on System, kept in step with the device — on
 * every screen, not only the one with the picker on it. It applies the palette as well, so the
 * one call at the root covers both.
 */
export function useThemePreference(_options: ThemePreferenceOptions = {}): ThemePreferenceState {
  const preference = useSyncExternalStore(subscribe, read, () => "system" as const);
  const palette = useSyncExternalStore(subscribe, readPalette, () => "default" as const);

  useEffect(() => {
    // The palette as well: another tab changing it reaches here, and nothing else repaints.
    apply(preference, palette);
    if (preference !== "system" || typeof window.matchMedia !== "function") return;
    // Following the device means repainting when the device changes, without a reload.
    const query = window.matchMedia(DARK_QUERY);
    const onChange = () => apply();
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, [preference, palette]);

  return [preference, setPreference] as const;
}

/**
 * The stored palette — `default` or one of `PALETTE_PREFERENCES` — and a setter that stores and
 * applies it. `useThemePreference` at the root already applies it; this is for the control that
 * changes it.
 */
export function usePalettePreference(
  _options: ThemePreferenceOptions = {},
): PalettePreferenceState {
  const palette = useSyncExternalStore(subscribe, readPalette, () => "default" as const);
  return [palette, setPalette] as const;
}

/**
 * The device's way in for a palette, which has no `<html>` to key off. On the web the palette is
 * `data-palette` and the stylesheet, so this is its children and nothing more — here so one root
 * compiles on both halves.
 */
export function PaletteProvider({ children }: { children?: ReactNode }) {
  return <Fragment>{children}</Fragment>;
}

/**
 * Light, Dark and System as three tiles — a `RadioGroup variant="card"`, so one tab stop and arrow
 * keys that move and choose come with it. One source for both platforms, compiled to the web item.
 *
 * Every app wrote this, and wrote the storage and the `<html>` class beside it: the control is the
 * small part. So by default the picker is **bound** — it reads and writes `useThemePreference()`,
 * which stores the choice and applies it, and there is nothing to wire. Pass `value` and it is
 * **controlled** instead: it only reports the choice through `onValueChange`, for an app that keeps
 * the preference somewhere of its own (on the account, in a settings form), and the hook is not
 * called at all, so nothing here paints over the app's own choice.
 *
 * `variant="compact"` is the same three choices where tiles do not fit — a sidebar footer, a phone
 * header bar: one row of icon-only segments (`RadioGroup variant="segmented"`) that fills its
 * container, so the caller sizes it. It is still a radiogroup of three radios, and each caption
 * ("Light", "Dark", "System") is the radio's accessible name. On the web the caption is also the
 * hover tooltip (`title`); device has no hover, so there the caption is what VoiceOver and TalkBack
 * read and nothing is shown.
 *
 * `palettes` adds a second choice under the first, of palette — `PALETTE_PREFERENCES`, or the ones
 * the app offers — bound to `usePalettePreference()` the same way, or controlled by `palette` and
 * `onPaletteChange`. While a dark-only palette is chosen the theme choice is disabled rather than
 * hidden: it still says what the app goes back to when the palette changes.
 */

import { View } from "react-native";
import { Monitor, Moon, Sun } from "@/components/ui/icons";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { usePalettePreference, useThemePreference } from "@/components/ui/theme-preference";
import {
  DARK_ONLY_PALETTES,
  isPalettePreference,
  isThemePreference,
  type PalettePreference,
  type ThemePreference,
} from "@/components/ui/theme-preference-base";
import { cn } from "@/lib/utils";

type ThemePickerProps = {
  /**
   * `card` (the default): three tiles, icon over caption, for a settings page. `compact`: one
   * full-width row of icon-only segments, the caption as the name and (on the web) the tooltip.
   */
  variant?: "card" | "compact" | undefined;
  /** The checked choice, for a controlled picker. Left out, the picker is bound to the hook. */
  value?: ThemePreference | undefined;
  /** Told of every choice — the only way a controlled picker changes; a bound one also stores it. */
  onValueChange?: ((value: ThemePreference) => void) | undefined;
  disabled?: boolean | undefined;
  id?: string | undefined;
  className?: string | undefined;
  /** The group's name. Defaults to "Theme"; pass `aria-labelledby` instead when a heading names it. */
  "aria-label"?: string | undefined;
  "aria-labelledby"?: string | undefined;
  "aria-describedby"?: string | undefined;
  /** Offer a palette as well, under the theme: these, in this order. Left out, no palette choice. */
  palettes?: readonly PalettePreference[] | undefined;
  /** The checked palette, for a controlled picker. Left out, the palette is bound to its hook. */
  palette?: PalettePreference | undefined;
  /** Told of every palette chosen; a bound picker also stores it. */
  onPaletteChange?: ((value: PalettePreference) => void) | undefined;
};

const PALETTE_OPTIONS: Record<PalettePreference, { label: string; description: string }> = {
  default: { label: "Default", description: "cubeui's own colours" },
  monokai: { label: "Monokai", description: "The editor theme. Dark only" },
};

const OPTIONS = [
  { value: "light", label: "Light", hint: "Always light", Icon: Sun },
  { value: "dark", label: "Dark", hint: "Always dark", Icon: Moon },
  { value: "system", label: "System", hint: "Follow the device", Icon: Monitor },
] as const;

function ThemeOptions({
  variant = "card",
  palettes: _palettes,
  palette: _palette,
  onPaletteChange: _onPaletteChange,
  value,
  onValueChange,
  disabled,
  id,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-describedby": ariaDescribedBy,
}: ThemePickerProps) {
  const compact = variant === "compact";
  return (
    <RadioGroup
      variant={compact ? "segmented" : "card"}
      value={value}
      onValueChange={(next) => {
        if (isThemePreference(next)) onValueChange?.(next);
      }}
      disabled={disabled}
      id={id}
      className={className}
      aria-label={ariaLabelledBy ? undefined : (ariaLabel ?? "Theme")}
      aria-labelledby={ariaLabelledBy}
      aria-describedby={ariaDescribedBy}
    >
      {OPTIONS.map(({ value: option, label, hint, Icon }) =>
        compact ? (
          // No `hint`: the segment's web tooltip is then its name, the caption a tile would show.
          <RadioGroupItem
            key={option}
            value={option}
            aria-label={label}
            icon={
              <Icon
                aria-hidden
                className={cn(
                  "h-4 w-4",
                  // Named, because a native icon has no `currentColor` to inherit from the segment.
                  value === option ? "text-selection-foreground" : "text-muted-foreground",
                )}
              />
            }
          />
        ) : (
          <RadioGroupItem
            key={option}
            value={option}
            label={label}
            hint={hint}
            icon={<Icon className="h-5 w-5" />}
          />
        ),
      )}
    </RadioGroup>
  );
}

function BoundThemePicker({ onValueChange, ...props }: ThemePickerProps) {
  const [preference, setPreference] = useThemePreference();
  return (
    <ThemeOptions
      {...props}
      value={preference}
      onValueChange={(next) => {
        setPreference(next);
        onValueChange?.(next);
      }}
    />
  );
}

function ThemeChoice(props: ThemePickerProps) {
  return props.value === undefined ? <BoundThemePicker {...props} /> : <ThemeOptions {...props} />;
}

type PaletteSectionProps = ThemePickerProps & { palettes: readonly PalettePreference[] };

function PaletteSection({
  palettes,
  palette,
  onPaletteChange,
  variant = "card",
  className,
  ...props
}: PaletteSectionProps) {
  const compact = variant === "compact";
  const darkOnly = palette !== undefined && DARK_ONLY_PALETTES.includes(palette);
  return (
    <View className={cn("gap-3", className)}>
      <ThemeChoice {...props} variant={variant} disabled={props.disabled || darkOnly} />
      <RadioGroup
        variant={compact ? "segmented" : "card"}
        value={palette}
        onValueChange={(next) => {
          if (isPalettePreference(next)) onPaletteChange?.(next);
        }}
        disabled={props.disabled}
        aria-label="Palette"
      >
        {palettes.map((option) => (
          <RadioGroupItem
            key={option}
            value={option}
            label={PALETTE_OPTIONS[option].label}
            description={compact ? undefined : PALETTE_OPTIONS[option].description}
            hint={compact ? PALETTE_OPTIONS[option].description : undefined}
          />
        ))}
      </RadioGroup>
    </View>
  );
}

function BoundPaletteSection({ onPaletteChange, ...props }: PaletteSectionProps) {
  const [palette, setPalette] = usePalettePreference();
  return (
    <PaletteSection
      {...props}
      palette={palette}
      onPaletteChange={(next) => {
        setPalette(next);
        onPaletteChange?.(next);
      }}
    />
  );
}

function ThemePicker(props: ThemePickerProps) {
  const { palettes } = props;
  if (!palettes) return <ThemeChoice {...props} />;
  return props.palette === undefined ? (
    <BoundPaletteSection {...props} palettes={palettes} />
  ) : (
    <PaletteSection {...props} palettes={palettes} />
  );
}

export type { ThemePickerProps };
export { ThemePicker };
